      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;0&lt;/OrderIndex&gt;
      &lt;ActionType&gt;RedirectToPage&lt;/ActionType&gt;
      &lt;ActionData&gt;{&quot;PageId&quot;:{&quot;IsExpression&quot;:false,&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;180&quot;},&quot;EnforceCurrentLocale&quot;:false,&quot;QueryString&quot;:null,&quot;QueryStringUseUrlProvider&quot;:true,&quot;OpenInPopup&quot;:false,&quot;PopupTitle&quot;:null,&quot;OpenInNewTab&quot;:false}&lt;/ActionData&gt;
